  <section id="hud" class="hidden" aria-label="Игровые показатели"><div class="progress-card"><div class="progress-label"><span>ПОГЛОЩЕНО</span><span>ЦЕЛЬ <b id="target-value">80</b>%</span></div><div class="progress-number"><span id="progress-value">0.00</span><small>%</small></div><div class="progress-track"><i id="progress-fill"></i><span></span></div><span class="mobile-target">из <b id="mobile-target">80</b>%</span><span id="mobile-radius" class="mobile-radius">18 м</span><button id="stats-toggle" aria-expanded="false" aria-controls="extra-stats" aria-label="Показать показатели">•••</button><div class="hud-location"><i></i><span id="hud-level"></span><span>100 КМ²</span></div></div><div id="extra-stats" class="stats-card"><div><span>РАДИУС</span><b id="radius-value">18 <small>м</small></b></div><div><span>ЗДАНИЯ</span><b id="count-value">0</b></div><div><span>ОЧКИ</span><b id="score-value">0</b></div><div><span>ВРЕМЯ</span><b id="time-value">00:00</b></div></div></section>
